using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------
var notes = new NoteTaker();

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(notes.AddNote),
    AIFunctionFactory.Create(notes.GetNotes),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. When the user gives you a topic:
    1. Search the web for relevant information (make several varied searches).
    2. Save important facts as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes and
       produce a well-structured summary with key findings and references.
    Be thorough but concise. Cite sources where possible.
    """;

// ---------------------------------------------------------------------------
// Conversation loop
// ---------------------------------------------------------------------------
Console.WriteLine("=== AI Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

var history = new List<ChatMessage> { new(ChatRole.System, systemPrompt) };

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new ChatMessage(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching… (the agent may call tools several times)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, chatOptions);
    history.AddRange(response.Messages);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

[Description("Search the web for a query and return a list of result snippets. " +
             "Use this to find information about a topic.")]
static async Task<string> SearchWeb(
    [Description("The search query string")] string query)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"  🔍  Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
        var html = await http.GetStringAsync(url);

        // Pull snippets from DuckDuckGo HTML results
        var snippets = Regex.Matches(html,
                @"<a rel=""nofollow"" class=""result__snippet""[^>]*>(.*?)</a>",
                RegexOptions.Singleline)
            .Cast<Match>()
            .Select(m => StripHtml(m.Groups[1].Value))
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .Take(6)
            .ToList();

        var titles = Regex.Matches(html,
                @"<a rel=""nofollow"" class=""result__a""[^>]*>(.*?)</a>",
                RegexOptions.Singleline)
            .Cast<Match>()
            .Select(m => StripHtml(m.Groups[1].Value))
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .Take(6)
            .ToList();

        if (snippets.Count == 0)
            return "No results found. Try a different query.";

        var sb = new StringBuilder();
        for (int i = 0; i < snippets.Count; i++)
        {
            var title = i < titles.Count ? titles[i] : "Result";
            sb.AppendLine($"[{i + 1}] {title}");
            sb.AppendLine($"    {snippets[i]}");
            sb.AppendLine();
        }
        return sb.ToString();
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

static string StripHtml(string html) =>
    WebUtility.HtmlDecode(Regex.Replace(html, "<.*?>", "")).Trim();

// ---------------------------------------------------------------------------
// Note-taking tool
// ---------------------------------------------------------------------------
class NoteTaker
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important facts, " +
                 "findings, or references discovered during research.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  📝  Note #{_notes.Count} saved");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
        return sb.ToString();
    }
}

